import { createTraffic } from '../../common/traffic';
import { createBoats } from '../../common/boats';
import { TP } from './profile';
import type { ThuanPhuocBridge } from './ThuanPhuocBridge';

/* [life] xe cộ & tàu thuyền (hệ dùng chung trong common/) */
export function tpBuildTraffic(bridge: ThuanPhuocBridge) {
  bridge.traffic = createTraffic(bridge, { seed: 405, x0: -1500, x1: 1480, busColor: 0x2f7fc1, lanes: [
    { off: TP.median / 2 + TP.laneWidth * 0.5, n: 20, speed: 16 },               // làn trong
    { off: TP.median / 2 + TP.laneWidth * 1.5, n: 30, speed: 11, bike: 0.6 }     // làn ngoài, nhiều xe máy
  ] });
}
export function tpBuildBoats(bridge: ThuanPhuocBridge) {
  // tàu cá, tàu du lịch và một tàu hàng nhỏ đi qua nhịp chính (tĩnh không 27 m)
  bridge.boats = createBoats(bridge, [
    { x: -70, z: 600, dir: -1, speed: 4.2, len: 22, w: 6.5, h: 2.6, cab: 2.6 },
    { x: 30, z: -500, dir: 1, speed: 3.4, len: 18, w: 6, h: 2.4, cab: 2.4 },
    { x: 110, z: 200, dir: -1, speed: 2.6, len: 46, w: 10, h: 4.2, cab: 7.5 }
  ]);
}
#### materials
import * as THREE from 'three';
import { makeLaneTexture } from '../../common/textures';
import { bridgePatch, patchWindows } from '../../common/shaders';
import { registerWet } from '../../environment/weather/wetness';

/* [materials] + [lighting]
   LED đổi màu dùng bridgePatch(), bảng màu 'sea': xanh dương → tím → hồng → xanh lá,
   dải màu chạy dọc cầu từ Tây sang Đông ("những cơn gió hướng ra biển"); chỉ sáng ban đêm */
export function tpMaterials() {
  const road = makeLaneTexture(2);
  const M = {
    concrete: bridgePatch(new THREE.MeshStandardMaterial({ color: 0xd6d3cc, roughness: 0.85, metalness: 0, vertexColors: true }), { noise: true, weather: true }),
    tower: bridgePatch(new THREE.MeshStandardMaterial({ color: 0xdedbd4, roughness: 0.84, metalness: 0, vertexColors: true }), { noise: true, led: 0.75, mode: 1, palette: 'sea', weather: true }),
    steel: bridgePatch(new THREE.MeshStandardMaterial({ color: 0xd2d7db, roughness: 0.4, metalness: 0.65 }), { weather: true }),
    cable: bridgePatch(new THREE.MeshStandardMaterial({ color: 0xc8ced3, roughness: 0.36, metalness: 0.75 }), { led: 2.6, palette: 'sea', sag: 'cable' }),   // võng thêm khi nóng (weather/summer.ts)
    hanger: bridgePatch(new THREE.MeshStandardMaterial({ color: 0xc8ced3, roughness: 0.38, metalness: 0.75 }), { led: 1.8, palette: 'sea', sway: 'tp', sag: 'hanger' }),   // hanger lắc theo gió (weather/wind.ts)
    joint: new THREE.MeshStandardMaterial({ color: 0x2c2f33, roughness: 0.5, metalness: 0.7 }),
    road: registerWet(new THREE.MeshStandardMaterial({ map: road, roughness: 0.93 })),   // mặt ướt khi mưa (weather/wetness.ts)
    beacon: new THREE.MeshBasicMaterial({ color: 0xff2a1a }),
    building: new THREE.MeshStandardMaterial({ color: 0xffffff, roughness: 0.75, metalness: 0.05 }),
    textures: [road] as THREE.Texture[]
  };
  patchWindows(M.building);
  return M;
}
export type TpMaterials = ReturnType<typeof tpMaterials>;
#### site
import * as THREE from 'three';
import { mergeGeometries } from 'three/addons/utils/BufferGeometryUtils.js';
import { CONFIG } from '../../config';
import { MAT } from '../../core/materials';
import { rng } from '../../common/math';
import { shadowed, zPlane } from '../../common/geometry';
import { TP } from './profile';
import type { ThuanPhuocBridge } from './ThuanPhuocBridge';

/* Mở rộng địa hình cửa sông quanh cầu: bờ đất, kè, đường ven sông, nhà, cây.
   Chỉ thêm khối mới, không sửa đất/đường hiện có của khu Cầu Rồng. Tọa độ cục bộ (z quanh 0 = tim cầu). */
export function tpBuildSite(bridge: ThuanPhuocBridge) {
  const z0 = TP.z, Y = CONFIG.landY, B = CONFIG.bankX, rnd = rng(1965);
  const wN = -3250 - z0, eN = -3700 - z0;                 // bờ biển phía Bắc (Tây / Đông), cục bộ
  const wS = -2600 - z0, eS = -2300 - z0;                 // mép đất hiện có
  const box = (x0: number, x1: number, za: number, zb: number, y0: number, y1: number) => { const g = new THREE.BoxGeometry(x1 - x0, y1 - y0, zb - za); g.translate((x0 + x1) / 2, (y0 + y1) / 2, (za + zb) / 2); return g; };
  bridge.group.add(shadowed(new THREE.Mesh(mergeGeometries([
    box(-14000, -B, wN, wS, -6, Y), box(B, 1480, eN, eS, -6, Y)
  ]), MAT.land), false, true));
  bridge.group.add(shadowed(new THREE.Mesh(box(1480, 1600, eN, eS, -6, 1.2), MAT.sand), false, true));
  bridge.group.add(shadowed(new THREE.Mesh(mergeGeometries([
    box(-B - 2, -B, wN, wS, -3, Y + 0.5), box(B, B + 2, eN, eS, -3, Y + 0.5),
    box(-3200, -B, wN - 2, wN, -3, Y + 0.5), box(B, 1480, eN - 2, eN, -3, Y + 0.5)
  ]), MAT.stone), false, true));
  bridge.group.add(shadowed(new THREE.Mesh(mergeGeometries([
    box(-B - 26, -B - 2, wN, wS, Y, Y + 0.05), box(B + 2, B + 26, eN, eS, Y, Y + 0.05)
  ]), MAT.paver), false, true));
  // đường ven sông nối dài: Như Nguyệt / Bạch Đằng (Tây), Trần Hưng Đạo (Đông)
  const roads = [], med = [];
  for (const [xc, za, zb] of [[-299, wN + 40, wS], [299, eN + 40, eS]]) {
    for (const s of [-1, 1]) {
      const g = zPlane(zb - za, 9, xc + s * 6, Y + 0.02, (za + zb) / 2, s < 0);
      const p = g.attributes.position, uv = g.attributes.uv;
      for (let i = 0; i < uv.count; i++) uv.setX(i, p.getZ(i) / 12);
      roads.push(g);
    }
    med.push(box(xc - 1.5, xc + 1.5, za, zb, Y, Y + 0.3));
  }
  const sr = shadowed(new THREE.Mesh(mergeGeometries(roads), MAT.road2), false, true);
  const sm = shadowed(new THREE.Mesh(mergeGeometries(med), MAT.grass), false, true);
  bridge.group.add(sr, sm); bridge.noReflect.push(sr, sm);
  // nhà thấp tầng / trung tầng quanh hai đầu cầu (ngoài hành lang cầu)
  const list: [number, number, number, number, number][] = [];
  const place = (xa: number, xb: number, za: number, zb: number, hMax: number) => {
    for (let x = xa; x < xb; x += 34) for (let z = za; z < zb; z += 34) {
      if (Math.abs(z) < 42 || rnd() < 0.3) continue;
      list.push([x + (rnd() - 0.5) * 8, z + (rnd() - 0.5) * 8, 12 + rnd() * 14, 12 + rnd() * 14, 8 + rnd() * hMax]);
    }
  };
  place(-1700, -360, wN + 60, wS - 20, 40);
  place(360, 1380, -400, eS - 20, 28);
  const bm = new THREE.InstancedMesh(new THREE.BoxGeometry(1, 1, 1).translate(0, 0.5, 0), bridge.mats.building, list.length);
  const m = new THREE.Matrix4(), q = new THREE.Quaternion(), v = new THREE.Vector3(), sc = new THREE.Vector3(), col = new THREE.Color();
  const palette = [0xf3f0e7, 0xeae2cf, 0xdadcdc, 0xcfe0e7, 0xe6dccb, 0xf6f6f2];
  list.forEach(([x, z, w, d, h], i) => {
    bm.setMatrixAt(i, m.compose(v.set(x, Y, z), q, sc.set(w, h, d)));
    bm.setColorAt(i, col.setHex(palette[Math.floor(rnd() * palette.length)]));
  });
  bm.castShadow = bm.receiveShadow = true;
  bridge.group.add(bm); bridge.noReflect.push(bm);
  // cây dọc kè mới
  const trees: [number, number][] = [];
  for (const [xs, za, zb] of [[-1, wN + 10, wS], [1, eN + 10, eS]]) for (let z = za; z < zb; z += 15) {
    if (Math.abs(z) < 26) continue;
    trees.push([xs * (B + 9 + rnd() * 12), z]);
  }
  const trunks = new THREE.InstancedMesh(new THREE.CylinderGeometry(0.22, 0.35, 1, 6).translate(0, 0.5, 0), MAT.trunk, trees.length);
  const crowns = new THREE.InstancedMesh(new THREE.SphereGeometry(1, 10, 8), MAT.leaf, trees.length);
  trees.forEach(([x, z], i) => {
    const h = 3 + rnd() * 2.5, r = 2.4 + rnd() * 1.8;
    trunks.setMatrixAt(i, m.compose(v.set(x, Y, z), q, sc.set(1, h, 1)));
    crowns.setMatrixAt(i, m.compose(v.set(x, Y + h + r * 0.6, z), q, sc.set(r, r * 0.85, r)));
    crowns.setColorAt(i, col.setHSL(0.27 + rnd() * 0.06, 0.45, 0.35 + rnd() * 0.12));
  });
  trunks.castShadow = crowns.castShadow = true;
  bridge.details.add(trunks, crowns);
}
#### towers
import * as THREE from 'three';
import { mergeGeometries } from 'three/addons/utils/BufferGeometryUtils.js';
import { lerp } from '../../common/math';
import { prepColored, wetLineColor, loftOct, boxAt } from '../../common/geometry';
import { TP, tpRoadY } from './profile';
import type { ThuanPhuocBridge } from './ThuanPhuocBridge';

/* [towers] tháp BTCT chữ H, yên ngựa, gối cầu, đèn báo hàng không */
export function tpBuildTowers(bridge: ThuanPhuocBridge) {
  const M = bridge.mats, towerParts = [], concrete = [], steel = [];
  const [b0x, b0z] = TP.legBase, [b1x, b1z] = TP.legTop;
  for (const sx of [-1, 1]) {
    const X = sx * TP.towerX;
    concrete.push(prepColored(boxAt(26, TP.pileCapTop + 6, 40, X, (TP.pileCapTop - 6) / 2, 0, 12), wetLineColor)); // bệ cọc
    for (const sz of [-1, 1]) {
      // bệ trụ dưới mỗi cột
      towerParts.push(prepColored(loftOct([b0x + 3.2, b0z + 3.0], [b0x + 2.2, b0z + 2.2], TP.pileCapTop, TP.plinthTop,
        [X, sz * (TP.legZBase + 0.2)], [X, sz * TP.legZBase], TP.chamfer * 1.6), wetLineColor));
      // cột tháp thon dần, nghiêng nhẹ vào trong
      towerParts.push(prepColored(loftOct([b0x, b0z], [b1x, b1z], TP.plinthTop, TP.towerTop,
        [X, sz * TP.legZBase], [X, sz * TP.legZTop], TP.chamfer)));
      // yên ngựa: hộp đế + nắp cong che cáp
      steel.push(boxAt(4.4, 0.8, 2.8, X, TP.towerTop + 0.4, sz * TP.cablePlaneZ));
