  bridge.pierNav.setMatrixAt(0, m.makeTranslation(0, SH.drumTop + 0.4, SH.drumR - 0.4));
  bridge.pierNav.setMatrixAt(1, m.makeTranslation(0, SH.drumTop + 0.4, -SH.drumR + 0.4));
