    const b = bridge.barrierSpec[i];
    qy.setFromAxisAngle(UP, b.sz > 0 ? 0 : Math.PI).multiply(q);
    bridge.arms.setMatrixAt(i, m.compose(v.set(b.x, shRoadY(b.x) + 1.15, b.z), qy, one));
